[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Fuel Price Trends &amp; Policy Impact Analysis (2020–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  /* ── Reset & Base ── */
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --blue-dark:   #0f2d5e;
    --blue-mid:    #1a4a8a;
    --blue-accent: #2563eb;
    --blue-light:  #dbeafe;
    --teal:        #0d9488;
    --amber:       #d97706;
    --red:         #dc2626;
    --green:       #16a34a;
    --slate-900:   #0f172a;
    --slate-700:   #334155;
    --slate-500:   #64748b;
    --slate-300:   #cbd5e1;
    --slate-100:   #f1f5f9;
    --white:       #ffffff;
    --font-sans:   'Segoe UI', system-ui, -apple-system, sans-serif;
    --font-mono:   'Consolas', 'Courier New', monospace;
    --r:           6px;
    --shadow:      0 2px 8px rgba(0,0,0,.12);
    --shadow-lg:   0 4px 20px rgba(0,0,0,.16);
  }
  html { scroll-behavior: smooth; }
  body {
    font-family: var(--font-sans);
    font-size: 14px;
    line-height: 1.6;
    color: var(--slate-700);
    background: var(--slate-100);
  }

  /* ── Cover Page ── */
  .cover {
    background: linear-gradient(135deg, var(--blue-dark) 0%, var(--blue-mid) 60%, #1e3a5f 100%);
    color: var(--white);
    min-height: 420px;
    padding: 60px 72px 48px;
    position: relative;
    overflow: hidden;
  }
  .cover::after {
    content: '';
    position: absolute; top: -80px; right: -80px;
    width: 400px; height: 400px;
    border-radius: 50%;
    background: rgba(255,255,255,.04);
    pointer-events: none;
  }
  .cover-badge {
    display: inline-block;
    background: rgba(255,255,255,.15);
    border: 1px solid rgba(255,255,255,.3);
    border-radius: 20px;
    padding: 4px 14px;
    font-size: 11px;
    letter-spacing: .08em;
    text-transform: uppercase;
    margin-bottom: 24px;
  }
  .cover h1 {
    font-size: 34px;
    font-weight: 700;
    line-height: 1.2;
    max-width: 780px;
    margin-bottom: 16px;
  }
  .cover .sub {
    font-size: 16px;
    opacity: .82;
    max-width: 640px;
    margin-bottom: 40px;
  }
  .cover-meta {
    display: flex; gap: 40px; flex-wrap: wrap;
    border-top: 1px solid rgba(255,255,255,.2);
    padding-top: 20px;
    font-size: 12px;
    opacity: .75;
  }
  .cover-meta span strong { display: block; font-size: 13px; opacity: 1; }

  /* ── Wrapper & Layout ── */
  .page { max-width: 1100px; margin: 0 auto; padding: 0 24px 80px; }

  /* ── TOC ── */
  .toc-block {
    background: var(--white);
    border-radius: var(--r);
    padding: 28px 36px;
    margin: 32px 0;
    box-shadow: var(--shadow);
  }
  .toc-block h2 {
    font-size: 13px; text-transform: uppercase; letter-spacing: .08em;
    color: var(--slate-500); margin-bottom: 16px;
  }
  .toc-list { list-style: none; columns: 2; column-gap: 40px; }
  .toc-list li { padding: 6px 0; border-bottom: 1px dashed var(--slate-300); }
  .toc-list a { color: var(--blue-accent); text-decoration: none; font-size: 13px; }
  .toc-list a:hover { text-decoration: underline; }
  .toc-num { color: var(--slate-500); margin-right: 6px; font-size: 11px; }

  /* ── Section Headers ── */
  .section {
    background: var(--white);
    border-radius: var(--r);
    padding: 36px 40px;
    margin-bottom: 28px;
    box-shadow: var(--shadow);
    page-break-inside: avoid;
  }
  .section-header {
    display: flex; align-items: flex-start;
    gap: 16px; margin-bottom: 24px;
    padding-bottom: 16px;
    border-bottom: 2px solid var(--blue-light);
  }
  .section-num {
    background: var(--blue-dark);
    color: var(--white);
    border-radius: 50%;
    width: 36px; height: 36px;
    display: flex; align-items: center; justify-content: center;
    font-size: 14px; font-weight: 700;
    flex-shrink: 0;
  }
  .section-header h2 { font-size: 20px; font-weight: 700; color: var(--slate-900); }
  .section-header .objective {
    font-size: 12px; color: var(--slate-500); margin-top: 3px; font-style: italic;
  }

  /* ── KPI Cards ── */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
  }
  .kpi {
    background: var(--slate-100);
    border-radius: var(--r);
    padding: 18px 20px;
    border-left: 4px solid var(--blue-accent);
  }
  .kpi.green  { border-left-color: var(--green); }
  .kpi.amber  { border-left-color: var(--amber); }
  .kpi.teal   { border-left-color: var(--teal);  }
  .kpi.red    { border-left-color: var(--red);   }
  .kpi-label  { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--slate-500); margin-bottom: 6px; }
  .kpi-value  { font-size: 26px; font-weight: 700; color: var(--slate-900); line-height: 1; }
  .kpi-sub    { font-size: 11px; color: var(--slate-500); margin-top: 4px; }

  /* ── Chart containers ── */
  .chart-wrap {
    position: relative;
    background: var(--slate-100);
    border-radius: var(--r);
    padding: 20px;
    margin-bottom: 24px;
  }
  .chart-title {
    font-size: 13px; font-weight: 700; color: var(--slate-700);
    margin-bottom: 14px; text-transform: uppercase; letter-spacing: .04em;
  }
  .chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 24px; }
  .chart-row .chart-wrap { margin-bottom: 0; }

  /* ── Tables ── */
  .tbl-wrap { overflow-x: auto; margin-bottom: 20px; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  thead th {
    background: var(--blue-dark);
    color: var(--white);
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 11px;
    letter-spacing: .04em;
    text-transform: uppercase;
    white-space: nowrap;
  }
  tbody tr:nth-child(even) { background: var(--slate-100); }
  tbody td { padding: 9px 14px; border-bottom: 1px solid var(--slate-300); }
  tbody tr:hover { background: var(--blue-light); }
  .num { text-align: right; font-variant-numeric: tabular-nums; }
  .bold { font-weight: 700; }
  .pill {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 11px;
    font-weight: 600;
    white-space: nowrap;
  }
  .pill-blue  { background: var(--blue-light); color: var(--blue-mid); }
  .pill-green { background: #dcfce7; color: var(--green); }
  .pill-amber { background: #fef3c7; color: var(--amber); }
  .pill-red   { background: #fee2e2; color: var(--red); }

  /* ── Callout / Finding ── */
  .callout {
    border-radius: var(--r);
    padding: 16px 20px;
    margin-bottom: 16px;
    display: flex; gap: 14px; align-items: flex-start;
  }
  .callout.info    { background: #eff6ff; border-left: 4px solid var(--blue-accent); }
  .callout.success { background: #f0fdf4; border-left: 4px solid var(--green); }
  .callout.warning { background: #fffbeb; border-left: 4px solid var(--amber); }
  .callout.danger  { background: #fef2f2; border-left: 4px solid var(--red); }
  .callout-icon { font-size: 18px; flex-shrink: 0; margin-top: 1px; }
  .callout-text { font-size: 13px; line-height: 1.55; }
  .callout-text strong { color: var(--slate-900); display: block; margin-bottom: 3px; }

  /* ── Findings numbered list ── */
  .finding-list { list-style: none; }
  .finding-list li {
    display: flex; gap: 16px; align-items: flex-start;
    padding: 14px 0;
    border-bottom: 1px solid var(--slate-300);
  }
  .finding-list li:last-child { border-bottom: none; }
  .finding-num {
    background: var(--blue-accent);
    color: var(--white);
    border-radius: 50%;
    width: 28px; height: 28px;
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 700;
    flex-shrink: 0;
  }
  .finding-body strong { color: var(--slate-900); font-size: 14px; }
  .finding-body p { font-size: 13px; color: var(--slate-700); margin-top: 3px; }

  /* ── Misc ── */
  .divider { border: none; border-top: 1px solid var(--slate-300); margin: 20px 0; }
  p { margin-bottom: 12px; font-size: 13.5px; }
  .text-muted { color: var(--slate-500); font-size: 12px; }
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .mt-0 { margin-top: 0; }
  .mb-0 { margin-bottom: 0; }
  .data-note {
    background: #fffbeb;
    border: 1px solid #fde68a;
    border-radius: var(--r);
    padding: 10px 14px;
    font-size: 12px;
    color: #92400e;
    margin-bottom: 16px;
  }
  .source-note {
    font-size: 11px;
    color: var(--slate-500);
    text-align: center;
    margin-top: 10px;
    font-style: italic;
  }

  @media print {
    body { background: white; }
    .section { box-shadow: none; border: 1px solid #ddd; }
  }
</style>
</head>
