<!-- ══════════════════════════════════════════════════════════════════════ -->
<!--  COVER                                                                 -->
<!-- ══════════════════════════════════════════════════════════════════════ -->
<div class="cover">
  <span class="cover-badge">Energy Policy Research &nbsp;|&nbsp; Global Analysis</span>
  <h1>Global Fuel Price Trends &amp;<br>Policy Impact Analysis</h1>
  <p class="sub">A comprehensive examination of retail fuel prices across 84 countries (2020–2026) — tracking how Brent Crude movements translate into pump prices and where government subsidies and taxation have succeeded or failed at shielding consumers from volatility.</p>
  <div class="cover-meta">
    <span><strong>Period Covered</strong>January 2020 – April 2026</span>
    <span><strong>Countries</strong>84 sovereign states</span>
    <span><strong>Regions</strong>7 geographic regions</span>
    <span><strong>Data Points</strong>27,468 weekly observations</span>
    <span><strong>Published</strong>April 2026</span>
    <span><strong>Audience</strong>Energy Policy Analysts</span>
  </div>
</div>

<div class="page">

<!-- ══════════════════════════════════════════════════════════════════════ -->
<!--  TABLE OF CONTENTS                                                     -->
<!-- ══════════════════════════════════════════════════════════════════════ -->
<div class="toc-block">
  <h2>Table of Contents</h2>
  <ul class="toc-list">
    <li><span class="toc-num">1</span><a href="#sec-overview">Global Fuel Price Overview</a></li>
    <li><span class="toc-num">2</span><a href="#sec-temporal">Temporal Price Trends &amp; Volatility</a></li>
    <li><span class="toc-num">3</span><a href="#sec-regional">Regional Price Disparities</a></li>
    <li><span class="toc-num">4</span><a href="#sec-subsidy">Impact of Subsidies &amp; Taxation</a></li>
    <li><span class="toc-num">5</span><a href="#sec-income">Fuel Affordability by Income Level</a></li>
    <li><span class="toc-num">6</span><a href="#sec-findings">Key Findings &amp; Policy Implications</a></li>
  </ul>
</div>

<!-- ══════════════════════════════════════════════════════════════════════ -->
<!--  SECTION 1 — GLOBAL OVERVIEW                                           -->
<!-- ══════════════════════════════════════════════════════════════════════ -->
<div class="section" id="sec-overview">
  <div class="section-header">
    <div class="section-num">1</div>
    <div>
      <h2>Global Fuel Price Overview</h2>
      <div class="objective">High-level summary statistics for petrol, diesel, and LPG across the full 2020–2026 period, with Brent Crude as the international benchmark baseline.</div>
    </div>
  </div>

  <div class="kpi-grid">
    <div class="kpi">
      <div class="kpi-label">Global Avg Petrol</div>
      <div class="kpi-value">$2.28</div>
      <div class="kpi-sub">USD / liter · 2020–2026</div>
    </div>
    <div class="kpi teal">
      <div class="kpi-label">Global Avg Diesel</div>
      <div class="kpi-value">$2.13</div>
      <div class="kpi-sub">USD / liter · 2020–2026</div>
    </div>
    <div class="kpi amber">
      <div class="kpi-label">Global Avg LPG</div>
      <div class="kpi-value">$1.71</div>
      <div class="kpi-sub">USD / liter · 2020–2026</div>
    </div>
    <div class="kpi green">
      <div class="kpi-label">Brent Crude Avg</div>
      <div class="kpi-value">$106.69</div>
      <div class="kpi-sub">USD / barrel · 2020–2026</div>
    </div>
    <div class="kpi red">
      <div class="kpi-label">Petrol Price Range</div>
      <div class="kpi-value">$0.01–$6.78</div>
      <div class="kpi-sub">USD / liter · min to max</div>
    </div>
    <div class="kpi">
      <div class="kpi-label">Brent Crude Range</div>
      <div class="kpi-value">$47.97–$130</div>
      <div class="kpi-sub">USD / barrel · min to max</div>
    </div>
    <div class="kpi teal">
      <div class="kpi-label">High-Subsidy Countries</div>
      <div class="kpi-value">22</div>
      <div class="kpi-sub">High + Very High subsidy</div>
    </div>
    <div class="kpi amber">
      <div class="kpi-label">Low-Subsidy Countries</div>
      <div class="kpi-value">44</div>
      <div class="kpi-sub">Low subsidy classification</div>
    </div>
  </div>

  <div class="data-note">
    <strong>Dataset:</strong> 27,468 weekly observations · 84 countries · 7 geographic regions · January 6, 2020 – April 6, 2026.
    All prices are denominated in USD per liter. Brent Crude is a global benchmark shared across all countries for a given week.
    Subsidy level is a national-level classification (High / Medium / Low / Very High); income level follows World Bank GNI per capita tiers.
  </div>

  <!-- Yearly summary table -->
  <div class="chart-title">Annual Price Summary — Petrol, Diesel, LPG &amp; Brent Crude</div>
  <div class="tbl-wrap">
    <table>
      <thead>
        <tr>
          <th>Year</th>
          <th class="num">Petrol ($/L)</th>
          <th class="num">Diesel ($/L)</th>
          <th class="num">LPG ($/L)</th>
          <th class="num">Brent ($/bbl)</th>
          <th class="num">Petrol YoY</th>
          <th class="num">Brent YoY</th>
        </tr>
      </thead>
      <tbody>
        <tr><td class="bold">2020</td><td class="num">1.485</td><td class="num">1.389</td><td class="num">1.114</td><td class="num">69.44</td><td class="num text-muted">—</td><td class="num text-muted">—</td></tr>
        <tr><td class="bold">2021</td><td class="num">2.280</td><td class="num">2.131</td><td class="num">1.710</td><td class="num">106.59</td><td class="num"><span class="pill pill-red">+53.5%</span></td><td class="num"><span class="pill pill-red">+53.5%</span></td></tr>
